-- Edições históricas (publicadas: entram na análise)
insert into public.exam_editions (exam_id, year, total_questions, status, published_at, source_name, source_checked_at)
select (select e.id from public.exams e join public.institutions i on i.id = e.institution_id where i.abbreviation = 'HU-UEL' and e.name = 'R1 Acesso Direto'), v.year, v.total, 'published', now(), 'Relatório "Análise das provas de R1 Acesso Direto — HU da UEL (2021–2026)" (Anexo A)', null
from (values (2021, 75), (2022, 75), (2023, 100), (2024, 100), (2025, 100), (2026, 100)) as v(year, total)
on conflict (exam_id, year) do update set total_questions = excluded.total_questions, source_name = excluded.source_name,
  source_checked_at = excluded.source_checked_at;

-- Próxima prova (data oficial quando houver; inscrição e valor são do aluno)
insert into public.exam_editions (exam_id, year, status, published_at, notes, exam_date)
values ((select e.id from public.exams e join public.institutions i on i.id = e.institution_id where i.abbreviation = 'HU-UEL' and e.name = 'R1 Acesso Direto'), 2027, 'published', now(), 'Próxima prova. Data oficial: 08/11/2026.', date '2026-11-08')
on conflict (exam_id, year) do update set notes = excluded.notes, exam_date = excluded.exam_date;

